import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"未濟","description":"东坡易传 - 未濟","frontmatter":{"title":"未濟","description":"东坡易传 - 未濟"},"headers":[],"relativePath":"zh/classics/dongpo/065.md","filePath":"zh/classics/dongpo/065.md"}'),o={name:"zh/classics/dongpo/065.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="未濟" tabindex="-1">未濟 <a class="header-anchor" href="#未濟" aria-label="Permalink to “未濟”">​</a></h1><p>“未濟”：亨；小狐汔濟，濡其尾；無攸利。</p><p>《彖》曰：“未濟，亨”，柔得中也【謂六五也】。 “小狐汔濟”，未出中也。“濡其尾，無攸利”，不續終也。雖不當位，剛柔應也。</p><p>“未濟”陽皆乘陰，上下之分定，未可以有爲也。“汔”，涸也。“坎”在“離”上，則水溢而火怒於下，必進之象也；是以雖溢而可以“濟”。“坎”在“離”下，則水涸而火安於上，不進之象也，是以雖涸而不可以“濟”。君子見其遠者、大者，小人見其小者、近者，初六、六三，小人也；見水之涸，以爲可濟也，是謂“小狐汔濟”。而九二君子也，以爲不可“曳其輪”而不進，則“小狐”安能獨濟哉！是謂“未出中也”。二陰輕進，而九二不予，是以六三“徵兇”。初六“濡其尾”，雖九二亦病矣，故“無攸利”。見易而輕犯之，遇難而退，雖有智者不能善其後，故曰“不續終也”。《易》二、三、四、五皆失位，惟“未濟”與“歸妹”也。故皆“無攸利”，而“歸妹”又“徵兇”者，剛柔不應也。</p><p>象曰：火在水上，“未濟”；君子以慎辨物居方。</p><p>上下方安其位，而不樂於進取，則君子慎靜其身，而辨物居方，以待其會。</p><p>初六：濡其尾，吝。象曰：“濡其尾”，亦不知極也。</p><p>水火相射，極乃致用。故“濟”必待其極，“汔濟”，非其極也。</p><p>九二：曳其輪，貞吉。象曰：九二“貞吉”，中以行正也。</p><p>外若不行，中以行正也。</p><p>六三：未濟，徵兇，利涉大川。象曰：“未濟徵兇”，位不當也。</p><p>“未濟”非不濟也，有所待之辭也。蓋將畜其全力，一用之於大難。大難既平，而小者隨之矣，故曰：“利涉大川”。六三見水之涸，幸其易濟而驟用之，後有大川，則其用廢矣，故曰“徵兇”。見涸而濟者，初與三均也；初“吝”而已，三至於“兇”，位不當也。</p><p>九四：貞吉，悔亡。震用伐鬼方，三年有賞於大國。象曰：“貞吉悔亡志行也。</p><p>九四有震主之威，苟不用於“鬼方”，則無所行其志矣，震主者悔也。貞於主而用於敵，所以“悔亡”也。</p><p>六五：貞吉，無悔。君子之光，有孚；吉。象曰：“君子之光”，其暉“吉”也。</p><p>光出於形之表，而不以力用。君子之廣大者也，下有九二，其應也；旁有九四、上九，其鄰也。險難未平，三者皆剛，莫能相用，將求用於我之不暇，非謀我者也。故六五信是三者，則三者爲之盡力，而我無爲，此“貞吉，無悔，君子之光”也。</p><p>上九：有孚於飲酒，無咎。濡其首，有孚，失是。象曰：“飲酒”濡首，亦不知節也。</p><p>“節”，事之會也。“是”，是時也。至於是而不濟，終不濟也。故“未濟”之可以濟者惟是也。險難未平，六五信我，將以用我也；我則飲酒而已，何也？將安以待其會也，故“無咎”。上九之謂首，“濡其首”者，可濟之時也；若不赴其節，飲酒於可濟之時，則信我者失是時矣。</p>',18)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
